const items = $input.all();
const rows = items.map(item => item.json.row);

const headerIndex = rows.findIndex(r => Array.isArray(r) && r.includes('FECHA'));
if (headerIndex === -1) {
  throw new Error('No se encontró la fila de cabecera con "FECHA"');
}
const headers = rows[headerIndex].map(h => String(h).trim());

function excelDateToJSDate(serial) {
  if (serial === undefined || serial === null || serial === '') return null;
  const utc_days = Math.floor(serial - 25569);
  const utc_value = utc_days * 86400;
  const date = new Date(utc_value * 1000);
  return date.toISOString().split('T')[0];
}

function decodeHtmlEntities(text) {
  if (!text || typeof text !== 'string') return text;
  const entities = {
    '&aacute;': 'á', '&eacute;': 'é', '&iacute;': 'í', '&oacute;': 'ó', '&uacute;': 'ú',
    '&ntilde;': 'ñ', '&Aacute;': 'Á', '&Eacute;': 'É', '&Iacute;': 'Í', '&Oacute;': 'Ó',
    '&Uacute;': 'Ú', '&Ntilde;': 'Ñ', '&amp;': '&', '&quot;': '"', '&#39;': "'"
  };
  return text.replace(/&[a-zA-Z]+;|&#\d+;/g, match => entities[match] || match);
}

const result = [];
for (let i = headerIndex + 1; i < rows.length; i++) {
  const row = rows[i];
  if (!Array.isArray(row) || row.length === 0) continue;

  const obj = {};
  headers.forEach((h, idx) => {
    obj[h] = row[idx] !== undefined ? row[idx] : null;
  });

  // Separar código de propiedad y dirección (formato "DEMO_001 – Calle Ejemplo 1")
  const propiedadTexto = obj['PROPIEDAD'] || '';
  const partes = propiedadTexto.split('–').map(p => p.trim());
  const codigoRentila = partes[0] || null;
  const direccion = partes[1] || propiedadTexto;

  const parsedRow = {
    fecha: excelDateToJSDate(obj['FECHA']),
    codigo_rentila: codigoRentila,
    direccion_propiedad: direccion,
    de_a: obj['DE/A'] || null,
    monto: obj['MONTO'] !== null && obj['MONTO'] !== undefined ? Number(obj['MONTO']) : null,
    tipo: obj['TIPO'] || null,
    descripcion: decodeHtmlEntities(obj['DESCRIPCION']) || null,
    estado: obj['ESTADO'] || null,
    pagado_en: excelDateToJSDate(obj['PAGADO EN']),
    pago: obj['PAGO'] || null
  };

  result.push({
    json: {
      ...parsedRow,
      origen_raw: JSON.stringify(obj)
    }
  });
}

return result;

const items = $input.all();

function excelDateToJSDate(serial) {
  if (serial === undefined || serial === null || serial === '') return null;
  const utc_days = Math.floor(serial - 25569);
  const utc_value = utc_days * 86400;
  const date = new Date(utc_value * 1000);
  return date.toISOString().split('T')[0];
}

function decodeHtmlEntities(text) {
  if (!text || typeof text !== 'string') return text;
  const entities = {
    '&aacute;': 'á', '&eacute;': 'é', '&iacute;': 'í', '&oacute;': 'ó', '&uacute;': 'ú',
    '&ntilde;': 'ñ', '&Aacute;': 'Á', '&Eacute;': 'É', '&Iacute;': 'Í', '&Oacute;': 'Ó',
    '&Uacute;': 'Ú', '&Ntilde;': 'Ñ', '&amp;': '&', '&quot;': '"', '&#39;': "'"
  };
  return text.replace(/&[a-zA-Z]+;|&#\d+;/g, match => entities[match] || match);
}

const result = [];
for (const item of items) {
  const obj = item.json;
  if (!obj['FECHA']) continue; // salta filas vacías si las hay

  const habitacionTexto = obj['HABITACIÓN'] || '';
  const partes = habitacionTexto.split('–').map(p => p.trim());
  const codigoRentila = partes[0] || null;
  const direccion = partes[1] || habitacionTexto;

  result.push({
    json: {
      fecha: excelDateToJSDate(obj['FECHA']),
      codigo_rentila: codigoRentila,
      direccion_propiedad: direccion,
      de_a: obj['DE/A'] || null,
      monto: obj['MONTO'] !== null && obj['MONTO'] !== undefined ? Number(obj['MONTO']) : null,
      tipo: obj['TIPO'] || null,
      descripcion: decodeHtmlEntities(obj['DESCRIPCION']) || null,
      referencia_pago: obj['PAGO'] || null,
      metodo_pago: obj['MÉTODO DE PAGO'] || null,
      origen_raw: JSON.stringify(obj)
    }
  });
}

return result;

const movimientos = $('Parsear Finanzas').all().length;
const regularizacion = $('Parsear Regularizacion').all().length;

return [{
  json: {
    movimientos_importados: movimientos,
    regularizacion_importada: regularizacion,
    total: movimientos + regularizacion
  }
}];
